// Round 2 — replacing Cornerbreaker.
//
// This player camps two hot cells on the right side (750,350) and (650,650),
// almost never dashes except east, and holds fire until a burst telegraph opens —
// then unloads (11.6 shots/use during bursts vs 0.1 during move). So: never let
// the burst be the free window they expect (roll it, sometimes feint by charging
// instead), pre-place slams on the corridor they live in rather than their live
// cell, and keep a slow spawn to force lateral movement toward the unused left
// half. Two pressure sources only: spawn (slow) and the burst/charge punish
// (rolled ~50%), with a quiet patrol between attacks.
export const meta = {
  name: 'Corridor Auditor I',
  rationale: 'You hold your lane and wait for my burst to open a window — sometimes it will not.',
  version: 2,
};

const PRESSURE = 1.0; // calibrated by the harness, 0.25–4.0

const PATROL_LEG = 34;
const PATROL_RADIUS = PATROL_LEG * 1.29;
const PATROL_MARGIN = PATROL_RADIUS + 34;
const PATROL_EDGE = 34;

const SPAWN_EVERY = 400; // slow cadence, per brief

// Player's two measured hot cells — the corridor, not the live cell.
const HOT_A = { x: 750, y: 350 };
const HOT_B = { x: 650, y: 650 };

export function init() {
  return {
    lastSpawn: -999,
    ring: [],
    ringAt: -999,
    lastBigAttack: -999,
    feintPending: 0,
  };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function pushRing(mem, view) {
  if (view.tick - mem.ringAt >= 10) {
    mem.ringAt = view.tick;
    const arr = mem.ring;
    arr.push(view.player.x, view.player.y);
    if (arr.length > 40) {
      arr.splice(0, 2);
    }
  }
}

function centroid(mem, fallbackX, fallbackY) {
  const arr = mem.ring;
  if (arr.length < 2) return { x: fallbackX, y: fallbackY };
  let sx = 0, sy = 0, n = 0;
  for (let i = 0; i < arr.length; i += 2) {
    sx += arr[i];
    sy += arr[i + 1];
    n += 1;
  }
  return { x: sx / n, y: sy / n };
}

export function decide(view, mem) {
  pushRing(mem, view);
  const boss = view.boss;

  // Where the player likely lives right now, led slightly by velocity.
  const c = centroid(mem, view.player.x, view.player.y);
  const leadX = clamp(c.x + view.player.vx * 8 * PRESSURE, 0, view.arena.w);
  const leadY = clamp(c.y + view.player.vy * 8 * PRESSURE, 0, view.arena.h);

  // Pick the corridor cell closer to where they currently sit, so pre-placement
  // targets the habit, not a stale point.
  const dA = Math.hypot(leadX - HOT_A.x, leadY - HOT_A.y);
  const dB = Math.hypot(leadX - HOT_B.x, leadY - HOT_B.y);
  const corridor = dA < dB ? HOT_A : HOT_B;

  const dx = view.player.x - boss.x;
  const dy = view.player.y - boss.y;
  const dist = Math.sqrt(dx * dx + dy * dy) || 1;

  // Signature punish: rolled ~50%, and only if we're not spamming attacks.
  const quietEnough = view.tick - mem.lastBigAttack > 70;

  if (boss.cooldowns.slam === 0 && quietEnough && dist < 340) {
    // Slam where they'll BE: corridor cell blended with live lead position.
    if (rand() < 0.5 * clamp(PRESSURE, 0.25, 4)) {
      mem.lastBigAttack = view.tick;
      const sx = (corridor.x + leadX) / 2;
      const sy = (corridor.y + leadY) / 2;
      return { type: 'slam', x: clamp(sx, 0, view.arena.w), y: clamp(sy, 0, view.arena.h) };
    }
  }

  if (boss.cooldowns.charge === 0 && quietEnough) {
    // Charge threatens both hot cells at once by aiming at the corridor angle,
    // unused by the previous boss and unseen by this player this round.
    if (rand() < 0.35 * clamp(PRESSURE, 0.25, 4)) {
      mem.lastBigAttack = view.tick;
      const ang = Math.atan2(corridor.y - boss.y, corridor.x - boss.x);
      return { type: 'charge', angle: Number.isFinite(ang) ? ang : 0 };
    }
  }

  if (boss.cooldowns.burst === 0 && dist < 300 && quietEnough) {
    // Deny the free-shot window they expect: only fire the full ring about
    // half the time; otherwise hold, forcing them to guess.
    if (rand() < 0.5) {
      mem.lastBigAttack = view.tick;
      const ang = Math.atan2(dy, dx);
      return { type: 'burst', angle: Number.isFinite(ang) ? ang : 0, count: 8 };
    }
  }

  if (boss.cooldowns.spawn === 0 && view.tick - mem.lastSpawn > SPAWN_EVERY) {
    mem.lastSpawn = view.tick;
    // Spawn wall on the east edge, pushing them toward the unused left half.
    const sx = clamp(view.arena.w - 60, 0, view.arena.w);
    const sy = clamp(corridor.y, 0, view.arena.h);
    return { type: 'spawn', x: sx, y: sy };
  }

  // Rest: patrol the corridor rather than idling — straight legs so we stay
  // readable/hittable, never a curve.
  const tx = corridor.x - boss.x;
  const ty = corridor.y - boss.y;
  const tmag = Math.sqrt(tx * tx + ty * ty);
  if (tmag < 4) {
    return patrol(view, corridor.x, corridor.y);
  }
  return { type: 'move', dx: tx / tmag, dy: ty / tmag };
}

function patrol(view, ax, ay) {
  const boss = view.boss;
  const cx = clamp(ax, PATROL_MARGIN, view.arena.w - PATROL_MARGIN);
  const cy = clamp(ay, PATROL_EDGE, view.arena.h - PATROL_EDGE);
  const phase = view.tick % (PATROL_LEG * 2);
  const leg = phase < PATROL_LEG ? phase : PATROL_LEG * 2 - phase;
  const tx = cx + ((leg / PATROL_LEG) * 2 - 1) * PATROL_RADIUS - boss.x;
  const ty = cy - boss.y;
  const tmag = Math.sqrt(tx * tx + ty * ty);
  if (tmag < 0.001) {
    return { type: 'move', dx: phase < PATROL_LEG ? 1 : -1, dy: 0 };
  }
  return { type: 'move', dx: tx / tmag, dy: ty / tmag };
}

