// Round 2 — replacing Cornerbreaker.
//
// This player camps two right-side cells, dashes almost only east, and holds
// fire until a burst telegraph opens. Blend: keep the reliable led-burst from
// the conservative build, but season it with the rolled slam/charge/spawn
// pressure so the corridor habit gets punished sometimes, not every time.
export const meta = {
  name: 'Signal Reaper I',
  rationale: 'You hold your fire for the opening in my burst and never leave your lane — so both are getting less predictable.',
  version: 2,
};

const PRESSURE = 1.0; // calibrated by the harness, 0.25-4.0

const HOLD_RANGE = 320;
const PATROL_LEG = 34;
const PATROL_RADIUS = PATROL_LEG * 1.29;

const HOT_A = { x: 750, y: 350 };
const HOT_B = { x: 650, y: 650 };

const SPAWN_EVERY = 600; // slower than B's, gated further by a roll

export function init() {
  return {
    lastSpawn: -999,
    ring: [],
    ringAt: -999,
    lastBigAttack: -999,
  };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function pushRing(mem, view) {
  if (view.tick - mem.ringAt >= 10) {
    mem.ringAt = view.tick;
    const arr = mem.ring;
    arr.push(view.player.x, view.player.y);
    if (arr.length > 40) arr.splice(0, 2);
  }
}

function centroid(mem, fx, fy) {
  const arr = mem.ring;
  if (arr.length < 2) return { x: fx, y: fy };
  let sx = 0, sy = 0, n = 0;
  for (let i = 0; i < arr.length; i += 2) { sx += arr[i]; sy += arr[i + 1]; n++; }
  return { x: sx / n, y: sy / n };
}

function patrol(view, boss, dist, dx, dy) {
  // Straight-leg lateral strafe, guaranteed nonzero.
  const phase = view.tick % (PATROL_LEG * 2);
  const dirSign = phase < PATROL_LEG ? 1 : -1;
  let perpx = -dy / (dist || 1);
  let perpy = dx / (dist || 1);
  if (!Number.isFinite(perpx) || !Number.isFinite(perpy) || (perpx === 0 && perpy === 0)) {
    perpx = 1; perpy = 0;
  }
  return { type: 'move', dx: perpx * dirSign, dy: perpy * dirSign };
}

export function decide(view, mem) {
  pushRing(mem, view);
  const boss = view.boss;
  const player = view.player;

  const dx = player.x - boss.x;
  const dy = player.y - boss.y;
  const dist = Math.sqrt(dx * dx + dy * dy) || 0.0001;

  const c = centroid(mem, player.x, player.y);
  const leadX = clamp(c.x + player.vx * 8 * PRESSURE, 0, view.arena.w);
  const leadY = clamp(c.y + player.vy * 8 * PRESSURE, 0, view.arena.h);

  const dA = Math.hypot(leadX - HOT_A.x, leadY - HOT_A.y);
  const dB = Math.hypot(leadX - HOT_B.x, leadY - HOT_B.y);
  const corridor = dA < dB ? HOT_A : HOT_B;

  const quietEnough = view.tick - mem.lastBigAttack > 70;

  // Rolled slam onto the corridor/lead blend — new rule from B, gated at 0.37.
  if (boss.cooldowns.slam === 0 && quietEnough && dist < 340) {
    if (rand() < 0.37 * clamp(PRESSURE, 0.25, 4)) {
      mem.lastBigAttack = view.tick;
      const sx = (corridor.x + leadX) / 2;
      const sy = (corridor.y + leadY) / 2;
      return { type: 'slam', x: clamp(sx, 0, view.arena.w), y: clamp(sy, 0, view.arena.h) };
    }
  }

  // Rolled charge threatening both hot cells — new rule from B, gated at 0.37.
  if (boss.cooldowns.charge === 0 && quietEnough) {
    if (rand() < 0.37 * 0.35 * clamp(PRESSURE, 0.25, 4)) {
      mem.lastBigAttack = view.tick;
      const ang = Math.atan2(corridor.y - boss.y, corridor.x - boss.x);
      return { type: 'charge', angle: Number.isFinite(ang) ? ang : 0 };
    }
  }

  // Core reliable pressure from A: led full-ring burst, fired most of the
  // time it's ready (blended 37% toward B's 50% roll from A's "always").
  const leadTicks = clamp(12 * PRESSURE, 4, 24);
  let tx = player.x + player.vx * leadTicks;
  let ty = player.y + player.vy * leadTicks;
  tx = clamp(tx, 0, view.arena.w);
  ty = clamp(ty, 0, view.arena.h);
  const bdx = tx - boss.x;
  const bdy = ty - boss.y;
  const bang = Math.atan2(bdy, bdx);
  const burstAngle = Number.isFinite(bang) ? bang : 0;

  if (boss.cooldowns.burst === 0) {
    if (rand() < 0.815) {
      mem.lastBigAttack = view.tick;
      return { type: 'burst', angle: burstAngle, count: 8 };
    }
  }

  // Slow, rolled spawn wall pushing the player toward the unused left half.
  if (boss.cooldowns.spawn === 0 && view.tick - mem.lastSpawn > SPAWN_EVERY) {
    if (rand() < 0.37) {
      mem.lastSpawn = view.tick;
      const sx = clamp(view.arena.w - 60, 0, view.arena.w);
      const sy = clamp(corridor.y, 0, view.arena.h);
      return { type: 'spawn', x: sx, y: sy };
    }
    mem.lastSpawn = view.tick; // don't re-roll every tick even on a miss
  }

  // Never punish contact: back off if too close.
  if (dist < HOLD_RANGE * 0.85) {
    const mx = boss.x - dx;
    const my = boss.y - dy;
    const mdist = Math.sqrt(mx * mx + my * my) || 0.0001;
    return { type: 'move', dx: mx / mdist, dy: my / mdist };
  }

  // Close gently toward holding range.
  if (dist > HOLD_RANGE * 1.15) {
    return { type: 'move', dx: dx / dist, dy: dy / dist };
  }

  // Otherwise: always keep moving, straight-leg patrol.
  return patrol(view, boss, dist, dx, dy);
}

