events.source:
// Round 2 — bisection blend between "conservative" (too easy) and "balanced"
// (too hard), moved 21% of the way from A toward B on every knob that B does
// more of: burst still fires almost every cooldown (was always-on in A, now
// rolled high), slam pre-placement on the camper's corridor is now a rare
// extra (gated), spawn cadence and charge threats are folded in at low odds.
// Never idle: always patrol or reposition.
export const meta = {
  name: 'Sentry Line III',
  rationale: 'You hold your lane and wait for my burst window — most of the time it still comes, but not always, and not always where you were standing.',
  version: 3,
};

const PRESSURE = 0.8425; // blended A(1.0) -> B(0.25) at 21%

const HOLD_RANGE = 320;
const PATROL_LEG = 34;
const PATROL_RADIUS = PATROL_LEG * 1.29;

// Player's measured hot cells (the corridor, not the live cell).
const HOT_A = { x: 750, y: 350 };
const HOT_B = { x: 650, y: 650 };

const SPAWN_EVERY = 1900; // slow, gated cadence blended toward B's 400

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

export function init() {
  return { ring: [], ringAt: -999, lastSpawn: -999, lastBig: -999 };
}

function pushRing(mem, view) {
  if (view.tick - mem.ringAt >= 10) {
    mem.ringAt = view.tick;
    const arr = mem.ring;
    arr.push(view.player.x, view.player.y);
    if (arr.length > 40) arr.splice(0, 2);
  }
}

function centroid(mem, fx, fy) {
  const arr = mem.ring;
  if (arr.length < 2) return { x: fx, y: fy };
  let sx = 0, sy = 0, n = 0;
  for (let i = 0; i < arr.length; i += 2) { sx += arr[i]; sy += arr[i + 1]; n++; }
  return { x: sx / n, y: sy / n };
}

function patrol(view, ax, ay) {
  const boss = view.boss;
  const cx = clamp(ax, PATROL_RADIUS + 34, view.arena.w - PATROL_RADIUS - 34);
  const cy = clamp(ay, 34, view.arena.h - 34);
  const phase = view.tick % (PATROL_LEG * 2);
  const leg = phase < PATROL_LEG ? phase : PATROL_LEG * 2 - phase;
  const tx = cx + ((leg / PATROL_LEG) * 2 - 1) * PATROL_RADIUS - boss.x;
  const ty = cy - boss.y;
  const tmag = Math.sqrt(tx * tx + ty * ty);
  if (tmag < 0.001) return { type: 'move', dx: phase < PATROL_LEG ? 1 : -1, dy: 0 };
  return { type: 'move', dx: tx / tmag, dy: ty / tmag };
}

export function decide(view, mem) {
  pushRing(mem, view);
  const boss = view.boss;
  const player = view.player;

  const dx = player.x - boss.x;
  const dy = player.y - boss.y;
  const dist = Math.sqrt(dx * dx + dy * dy) || 0.0001;

  const c = centroid(mem, player.x, player.y);
  const leadX = clamp(c.x + player.vx * 8 * PRESSURE, 0, view.arena.w);
  const leadY = clamp(c.y + player.vy * 8 * PRESSURE, 0, view.arena.h);

  const dA = Math.hypot(leadX - HOT_A.x, leadY - HOT_A.y);
  const dB = Math.hypot(leadX - HOT_B.x, leadY - HOT_B.y);
  const corridor = dA < dB ? HOT_A : HOT_B;

  const quiet = view.tick - mem.lastBig > 60;

  // Rare pre-placed slam on the camper's corridor, blended in from B at 21%.
  if (boss.cooldowns.slam === 0 && quiet && dist < 340) {
    if (rand() < 0.21) {
      mem.lastBig = view.tick;
      const sx = (corridor.x + leadX) / 2;
      const sy = (corridor.y + leadY) / 2;
      return { type: 'slam', x: clamp(sx, 0, view.arena.w), y: clamp(sy, 0, view.arena.h) };
    }
  }

  // Rare charge threat toward the corridor, blended in from B at low odds.
  if (boss.cooldowns.charge === 0 && quiet) {
    if (rand() < 0.21 * 0.35) {
      mem.lastBig = view.tick;
      const ang = Math.atan2(corridor.y - boss.y, corridor.x - boss.x);
      return { type: 'charge', angle: Number.isFinite(ang) ? ang : 0 };
    }
  }

  // Signature burst: led onto predicted position, fired almost every time
  // it's off cooldown (rolled high, not always, moved 21% toward B's 0.5).
  const leadTicks = clamp(12 * PRESSURE, 4, 24);
  let tx = player.x + player.vx * leadTicks;
  let ty = player.y + player.vy * leadTicks;
  tx = clamp(tx, 0, view.arena.w);
  ty = clamp(ty, 0, view.arena.h);
  const bdx = tx - boss.x;
  const bdy = ty - boss.y;
  const angle = Math.atan2(bdy, bdx);

  if (boss.cooldowns.burst === 0) {
    if (rand() < 0.895) {
      return { type: 'burst', angle: Number.isFinite(angle) ? angle : 0, count: 8 };
    }
  }

  // Slow spawn wall on the east edge, gated in from B, forcing lateral play.
  if (boss.cooldowns.spawn === 0 && view.tick - mem.lastSpawn > SPAWN_EVERY) {
    if (rand() < 0.21) {
      mem.lastSpawn = view.tick;
      const sx = clamp(view.arena.w - 60, 0, view.arena.w);
      const sy = clamp(corridor.y, 0, view.arena.h);
      return { type: 'spawn', x: sx, y: sy };
    }
  }

  // Never punish contact: if too close, back off toward holding range.
  if (dist < HOLD_RANGE * 0.85) {
    const mx = boss.x - dx;
    const my = boss.y - dy;
    const mdist = Math.sqrt(mx * mx + my * my) || 0.0001;
    return { type: 'move', dx: mx / mdist, dy: my / mdist };
  }

  if (dist > HOLD_RANGE * 1.15) {
    return { type: 'move', dx: dx / dist, dy: dy / dist };
  }

  // Rest: patrol the corridor with straight legs, never idle.
  return patrol(view, corridor.x, corridor.y);
}

