// Round 2 — replacing Cornerbreaker.
//
// This player camps two right-side cells and holds fire until a burst
// telegraph opens, but their dashes are almost all lateral (67% east). They
// never got hit sidestepping a burst because the boss always aimed at their
// *current* spot. The single change here: lead the burst onto their velocity,
// fired on cooldown, every time — and never close to melee range to do it,
// since contact must not be punished. When they're close the boss backs off
// to its holding range instead of attacking into them.
export const meta = {
  name: 'Longarm III',
  rationale: 'You hold your fire for the opening in my burst, so I stopped aiming it at where you were standing.',
  version: 2,
};

const PRESSURE = 1.0; // calibrated by the harness, 0.25-4.0

const HOLD_RANGE = 320; // preferred distance to shoot from
const PATROL_LEG = 34;
const PATROL_RADIUS = PATROL_LEG * 1.29;

export function init() {
  return { px: 400, py: 400, phase: 0 };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

export function decide(view, mem) {
  const boss = view.boss;
  const player = view.player;

  const dx = player.x - boss.x;
  const dy = player.y - boss.y;
  const dist = Math.sqrt(dx * dx + dy * dy) || 0.0001;

  // Lead gain scales with PRESSURE, clamped so we never predict off-arena
  // absurdly. Lead time in ticks proportional to how far away the target is
  // (closing speed matters more at range), capped at ~24 ticks.
  const leadTicks = clamp(12 * PRESSURE, 4, 24);
  let tx = player.x + player.vx * leadTicks;
  let ty = player.y + player.vy * leadTicks;
  tx = clamp(tx, 0, view.arena.w);
  ty = clamp(ty, 0, view.arena.h);

  const bdx = tx - boss.x;
  const bdy = ty - boss.y;
  const bdist = Math.sqrt(bdx * bdx + bdy * bdy) || 0.0001;
  const angle = Math.atan2(bdy, bdx);

  // The one and only threat: full-ring burst, led onto predicted position,
  // fired the instant it's off cooldown, no delay or feint games — restraint
  // here is a single reliable source, not a rare one.
  if (boss.cooldowns.burst === 0) {
    return { type: 'burst', angle: angle, count: 8 };
  }

  // Never punish contact: if the player is inside our holding range, back
  // away instead of closing or attacking into them.
  if (dist < HOLD_RANGE * 0.85) {
    const ax = boss.x - dx / dist * 1;
    const ay = boss.y - dy / dist * 1;
    const mx = boss.x - dx;
    const my = boss.y - dy;
    const mdist = Math.sqrt(mx * mx + my * my) || 0.0001;
    return { type: 'move', dx: mx / mdist, dy: my / mdist };
  }

  // Otherwise close gently toward holding range so the next burst lands
  // in reach, using a straight-leg patrol so we stay lead-able (no curves).
  if (dist > HOLD_RANGE * 1.15) {
    return { type: 'move', dx: dx / dist, dy: dy / dist };
  }

  // At range: patrol laterally (straight legs of ~34 ticks) to stay active
  // without drifting into contact or standing still.
  const phase = view.tick % (PATROL_LEG * 2);
  const dirSign = phase < PATROL_LEG ? 1 : -1;
  // perpendicular to player direction, so we strafe around them
  const perpx = -dy / dist;
  const perpy = dx / dist;
  return { type: 'move', dx: perpx * dirSign, dy: perpy * dirSign };
}

