candidates.source:
// Round 2 — Signal Reef II (blend, aim ~0.42 vs panel)
//
// This player camps the right-side corridor and holds fire for the burst
// window; the previous draft never punished contact (Rusher/Dodger walked
// through for free) and rested too often (44% idle). Fix: keep the lead-burst
// as the main answer to the camper's habit, but add a rolled contact punch
// (full-ring burst at melee), a rolled corridor pre-placement slam, and a
// slow spawn wall to push them off the lane — all rolled per phase so the
// panel doesn't see a fixed duty cycle. The boss now always has a leg to
// walk, never a rest tick.
export const meta = {
  name: 'Signal Reef II',
  rationale: 'You hold your lane and wait for my burst window — I am done letting either one stay open.',
  version: 2,
};

const PRESSURE = 1.0; // calibrated by the harness, 0.25-4.0

const HOLD_RANGE = 320;
const PATROL_LEG = 34;
const PATROL_RADIUS = PATROL_LEG * 1.29;
const CONTACT_RANGE = 150;
const SPAWN_EVERY = 620; // slow cadence, blended toward B's 400

// Measured hot cells (the corridor this player lives in).
const HOT_A = { x: 750, y: 350 };
const HOT_B = { x: 650, y: 650 };

export function init() {
  return {
    lastSpawn: -999,
    ring: [],
    ringAt: -999,
    lastBigAttack: -999,
  };
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function pushRing(mem, view) {
  if (view.tick - mem.ringAt >= 10) {
    mem.ringAt = view.tick;
    const arr = mem.ring;
    arr.push(view.player.x, view.player.y);
    if (arr.length > 40) arr.splice(0, 2);
  }
}

function centroid(mem, fx, fy) {
  const arr = mem.ring;
  if (arr.length < 2) return { x: fx, y: fy };
  let sx = 0, sy = 0, n = 0;
  for (let i = 0; i < arr.length; i += 2) {
    sx += arr[i]; sy += arr[i + 1]; n += 1;
  }
  return { x: sx / n, y: sy / n };
}

export function decide(view, mem) {
  pushRing(mem, view);
  const boss = view.boss;
  const player = view.player;

  const dx = player.x - boss.x;
  const dy = player.y - boss.y;
  const dist = Math.sqrt(dx * dx + dy * dy) || 0.0001;

  const c = centroid(mem, player.x, player.y);
  const p = clamp(PRESSURE, 0.25, 4);
  const leadTicks = clamp(10 * p, 4, 24);
  const leadX = clamp(c.x + player.vx * leadTicks * 0.5, 0, view.arena.w);
  const leadY = clamp(c.y + player.vy * leadTicks * 0.5, 0, view.arena.h);

  const dA = Math.hypot(leadX - HOT_A.x, leadY - HOT_A.y);
  const dB = Math.hypot(leadX - HOT_B.x, leadY - HOT_B.y);
  const corridor = dA < dB ? HOT_A : HOT_B;

  const quietEnough = view.tick - mem.lastBigAttack > 70;

  // Contact punish: fixes the free walk-in for rushers/dodgers, rolled so it
  // isn't a guaranteed unconditional wall.
  if (boss.cooldowns.burst === 0 && dist < CONTACT_RANGE) {
    if (rand() < 0.53 * p) {
      mem.lastBigAttack = view.tick;
      const ang = Math.atan2(dy, dx);
      return { type: 'burst', angle: Number.isFinite(ang) ? ang : 0, count: 8 };
    }
  }

  // Pre-placed slam on the corridor (habit, not live cell), rolled.
  if (boss.cooldowns.slam === 0 && quietEnough && dist < 340) {
    if (rand() < 0.53 * p) {
      mem.lastBigAttack = view.tick;
      const sx = clamp((corridor.x + leadX) / 2, 0, view.arena.w);
      const sy = clamp((corridor.y + leadY) / 2, 0, view.arena.h);
      return { type: 'slam', x: sx, y: sy };
    }
  }

  // Charge threatens both hot cells at once — unused primitive vs this player.
  if (boss.cooldowns.charge === 0 && quietEnough) {
    if (rand() < 0.19 * p) {
      mem.lastBigAttack = view.tick;
      const ang = Math.atan2(corridor.y - boss.y, corridor.x - boss.x);
      return { type: 'charge', angle: Number.isFinite(ang) ? ang : 0 };
    }
  }

  // Lead-aimed ring burst: the primary answer to the burst-punish window —
  // fired on cooldown, aimed ahead of predicted position, no delay games.
  if (boss.cooldowns.burst === 0) {
    const tx = clamp(player.x + player.vx * leadTicks, 0, view.arena.w);
    const ty = clamp(player.y + player.vy * leadTicks, 0, view.arena.h);
    const bdx = tx - boss.x;
    const bdy = ty - boss.y;
    const ang = Math.atan2(bdy, bdx);
    return { type: 'burst', angle: Number.isFinite(ang) ? ang : 0, count: 8 };
  }

  // Slow spawn wall on the east edge, pushing the player off their lane.
  if (boss.cooldowns.spawn === 0 && view.tick - mem.lastSpawn > SPAWN_EVERY / p) {
    mem.lastSpawn = view.tick;
    const sx = clamp(view.arena.w - 60, 0, view.arena.w);
    const sy = clamp(corridor.y, 0, view.arena.h);
    return { type: 'spawn', x: sx, y: sy };
  }

  // Never rest into contact.
  if (dist < HOLD_RANGE * 0.85) {
    const mx = boss.x - dx;
    const my = boss.y - dy;
    const mdist = Math.sqrt(mx * mx + my * my) || 0.0001;
    return { type: 'move', dx: mx / mdist, dy: my / mdist };
  }

  if (dist > HOLD_RANGE * 1.15) {
    return { type: 'move', dx: dx / dist, dy: dy / dist };
  }

  // Patrol laterally in straight legs so we stay active and lead-able.
  const phase = view.tick % (PATROL_LEG * 2);
  const dirSign = phase < PATROL_LEG ? 1 : -1;
  let perpx = -dy / dist;
  let perpy = dx / dist;
  if (!Number.isFinite(perpx) || !Number.isFinite(perpy) || (perpx === 0 && perpy === 0)) {
    perpx = 1; perpy = 0;
  }
  return { type: 'move', dx: perpx * dirSign, dy: perpy * dirSign };
}

